// MFA login step 1 → step 2 handoff (DOCB-13743). Mirror of
// org-selection-pending.ts: when a login needs a second factor the auth service
// withholds the full token and returns { mfa_required, mfa_token, methods }.
// Login.vue has no token to act on yet — only the short-lived, single-use
// mfa_token — so it must survive a navigation to /mfa-challenge without ever
// touching LocalStorage (must not outlive the tab, must not be mistaken for a
// real session). SessionStorage is exactly that lifetime.

import { SessionStorage } from 'quasar';
import type { ApiRegion } from 'src/pages/APIs';

const STORAGE_KEY = 'mfa_pending';

/** Shape of the mfa-required response from the token endpoint. */
export interface MfaRequiredResponse {
  mfa_required: true;
  mfa_token: string;
  methods: string[];
}

/** The org-enforced-but-not-enrolled variant (no factor yet). */
export interface MfaEnrollmentRequiredResponse {
  mfa_enrollment_required: true;
  mfa_token: string;
}

/**
 * Narrows to the org-enforced-but-not-enrolled variant (DOCB-13959). The org
 * requires MFA but this account has no factor yet, so there is nothing to
 * challenge — Login.vue surfaces an actionable message instead of a token.
 */
export function isMfaEnrollmentRequired(
  response: unknown,
): response is MfaEnrollmentRequiredResponse {
  const r = response as
    | Partial<MfaEnrollmentRequiredResponse>
    | null
    | undefined;
  return (
    !!r &&
    r.mfa_enrollment_required === true &&
    typeof r.mfa_token === 'string'
  );
}

/** Narrows an arbitrary login response to the mfa-required variant. */
export function isMfaRequired(response: unknown): response is MfaRequiredResponse {
  const r = response as Partial<MfaRequiredResponse> | null | undefined;
  return (
    !!r &&
    r.mfa_required === true &&
    typeof r.mfa_token === 'string' &&
    Array.isArray(r.methods)
  );
}

export interface MfaPending {
  mfaToken: string;
  /** Enrolled factors offered, e.g. ['totp', 'backup']. */
  methods: string[];
  /** Route to continue to after the second factor verifies (mirrors Login.vue's `redirect`). */
  redirect: string;
  /** Mirrors Login.vue's `needsReloadForRegion` — hard reload instead of router.push. */
  forceFullReload: boolean;
  /** The auth region the login used, so the verify call hits the SAME auth service. */
  authRegion?: ApiRegion;
}

export function storeMfaPending(pending: MfaPending): void {
  SessionStorage.set(STORAGE_KEY, pending);
}

/** Reads and clears the pending challenge in one step — single-use, like the server token. */
export function takeMfaPending(): MfaPending | null {
  const pending = SessionStorage.getItem(STORAGE_KEY) as MfaPending | null;
  SessionStorage.remove(STORAGE_KEY);
  return pending ?? null;
}
